-- Step 1: Find the cmd.exe process with PID 336 and the time it executed run_http_server.bat
SELECT time, pid, ppid, pname, process_name, command_line FROM audit_logs
WHERE pname = 'cmd.exe' AND pid = 336 AND command_line LIKE '%run_http_server.bat%';

